import os

search_term = "agency_analyzer_v2_fixed"
search_dir = "storage/shared/agency_lab/"
found_files = []

print(f"--- Searching for '{search_term}' in '{search_dir}' ---")

for root, dirs, files in os.walk(search_dir):
    for file in files:
        if file.endswith(".py"):
            file_path = os.path.join(root, file)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                    if search_term in content:
                        found_files.append(file_path)
            except Exception as e:
                print(f"Could not read {file_path}: {e}")

if found_files:
    print("Found the following files referencing the correct analyzer:")
    for path in found_files:
        print(f"- {path}")
else:
    print("No files found referencing the correct analyzer. The script may be in an evaluation log.")

print("--- Search Complete ---")
